/**
 * Minimal OpenAPI reader for the in-app API reference.
 *
 * The document it consumes is generated by the evaluation service from its own
 * FastAPI routes, so everything rendered here — paths, parameters, field types,
 * response shapes — comes from the running code. There is no second, hand-kept
 * description that could quietly fall out of date.
 *
 * Only the slice of OpenAPI our own generator emits is handled; this is not a
 * general-purpose spec renderer.
 */

export interface OpenApiSpec {
	openapi?: string;
	info?: { title?: string; version?: string; description?: string };
	paths?: Record<string, Record<string, RawOperation>>;
	components?: { schemas?: Record<string, Schema>; securitySchemes?: Record<string, Schema> };
}

export type Schema = Record<string, any>;

interface RawOperation {
	summary?: string;
	description?: string;
	parameters?: Schema[];
	requestBody?: Schema;
	responses?: Record<string, Schema>;
}

export interface Operation {
	id: string;
	method: string;
	path: string;
	summary: string;
	description: string;
	parameters: Schema[];
	requestSchema: Schema | null;
	responses: { status: string; description: string; schema: Schema | null }[];
}

const HTTP_METHODS = ['get', 'post', 'put', 'patch', 'delete'];
const MAX_DEPTH = 4;

/** Follow `$ref` chains into `components.schemas`. */
export function deref(schema: Schema | null | undefined, spec: OpenApiSpec): Schema {
	let current = schema ?? {};
	// Bounded: a self-referencing model would otherwise loop forever.
	for (let i = 0; i < 10 && typeof current.$ref === 'string'; i++) {
		const name = current.$ref.split('/').pop() ?? '';
		current = spec.components?.schemas?.[name] ?? {};
	}
	return current;
}

/** Name of the model a `$ref` points at, or null for inline schemas. */
export function refName(schema: Schema | null | undefined): string | null {
	const ref = schema?.$ref;
	return typeof ref === 'string' ? (ref.split('/').pop() ?? null) : null;
}

/**
 * Human-readable type, e.g. `string`, `string | null`, `ChatResult[]`.
 *
 * Optional fields arrive as `anyOf: [{…}, {type: "null"}]` from Pydantic, which
 * is accurate but unreadable in a table.
 */
export function typeLabel(schema: Schema | null | undefined, spec: OpenApiSpec): string {
	if (!schema) return 'any';

	const named = refName(schema);
	if (named) return named;

	if (Array.isArray(schema.anyOf)) {
		return schema.anyOf.map((option: Schema) => typeLabel(option, spec)).join(' | ');
	}

	if (schema.type === 'array') {
		const inner = typeLabel(schema.items, spec);
		// Parenthesise unions so "string | null[]" cannot be misread.
		return inner.includes('|') ? `(${inner})[]` : `${inner}[]`;
	}

	if (schema.type === 'null') return 'null';
	if (schema.type === 'object' && !schema.properties) return 'object';
	return (schema.type as string) ?? 'any';
}

/**
 * Build a realistic example value for a schema.
 *
 * Declared examples win — they are the ones written next to the field in the
 * Python source, so they are the ones an integrator should copy.
 */
export function sampleValue(
	schema: Schema | null | undefined,
	spec: OpenApiSpec,
	depth = 0
): unknown {
	const resolved = deref(schema, spec);

	if (Array.isArray(resolved.examples) && resolved.examples.length) return resolved.examples[0];
	if (resolved.example !== undefined) return resolved.example;
	if (resolved.default !== undefined) return resolved.default;
	if (Array.isArray(resolved.enum) && resolved.enum.length) return resolved.enum[0];

	if (Array.isArray(resolved.anyOf)) {
		const concrete =
			resolved.anyOf.find((o: Schema) => o.type !== 'null') ?? resolved.anyOf[0];
		return concrete ? sampleValue(concrete, spec, depth) : null;
	}

	if (resolved.properties || resolved.type === 'object') {
		if (depth >= MAX_DEPTH) return {};
		const out: Record<string, unknown> = {};
		for (const [key, prop] of Object.entries(resolved.properties ?? {})) {
			out[key] = sampleValue(prop as Schema, spec, depth + 1);
		}
		return out;
	}

	if (resolved.type === 'array') {
		if (depth >= MAX_DEPTH) return [];
		return [sampleValue(resolved.items, spec, depth + 1)];
	}

	switch (resolved.type) {
		case 'integer':
			return 0;
		case 'number':
			return 0;
		case 'boolean':
			return true;
		case 'null':
			return null;
		default:
			return 'string';
	}
}

export interface PropertyRow {
	name: string;
	type: string;
	required: boolean;
	description: string;
	defaultValue: string;
}

/** Flatten a model into table rows: name, type, required, description. */
export function propertyRows(schema: Schema | null | undefined, spec: OpenApiSpec): PropertyRow[] {
	const resolved = deref(schema, spec);
	const required = new Set<string>((resolved.required as string[]) ?? []);
	return Object.entries(resolved.properties ?? {}).map(([name, raw]) => {
		const prop = raw as Schema;
		return {
			name,
			type: typeLabel(prop, spec),
			required: required.has(name),
			description: (prop.description as string) ?? '',
			defaultValue: prop.default === undefined ? '' : JSON.stringify(prop.default)
		};
	});
}

function successResponse(responses: Record<string, Schema> | undefined): Schema | null {
	for (const [status, response] of Object.entries(responses ?? {})) {
		if (!status.startsWith('2')) continue;
		const schema = response.content?.['application/json']?.schema;
		if (schema) return schema;
	}
	return null;
}

/** Every documented operation, in the order the generator emitted them. */
export function listOperations(spec: OpenApiSpec): Operation[] {
	const operations: Operation[] = [];
	for (const [path, item] of Object.entries(spec.paths ?? {})) {
		for (const method of HTTP_METHODS) {
			const raw = item[method];
			if (!raw) continue;
			operations.push({
				id: `${method}-${path}`.replace(/[^a-zA-Z0-9]+/g, '-').toLowerCase(),
				method: method.toUpperCase(),
				path,
				summary: raw.summary ?? path,
				description: raw.description ?? '',
				parameters: raw.parameters ?? [],
				requestSchema: raw.requestBody?.content?.['application/json']?.schema ?? null,
				responses: Object.entries(raw.responses ?? {})
					.sort(([a], [b]) => a.localeCompare(b))
					.map(([status, response]) => ({
						status,
						description: (response.description as string) ?? '',
						schema: response.content?.['application/json']?.schema ?? null
					}))
			});
		}
	}
	return operations;
}

/**
 * The 2xx body shape, for the "Antwort" table.
 *
 * `null` when the operation documents no schema — the full-trace endpoint
 * genuinely returns free-form JSON. Every reader above accepts `null` so
 * callers can pass this straight through.
 */
export function responseSchema(operation: Operation): Schema | null {
	for (const response of operation.responses) {
		if (response.status.startsWith('2') && response.schema) return response.schema;
	}
	return null;
}

/** Substitute `{request_id}` with the example declared next to the parameter. */
function fillPath(operation: Operation, spec: OpenApiSpec): string {
	let filled = operation.path;
	for (const parameter of operation.parameters) {
		if (parameter.in !== 'path') continue;
		const value = sampleValue(parameter.schema, spec);
		const rendered =
			typeof value === 'string' && value !== 'string' ? value : `<${parameter.name}>`;
		filled = filled.replace(`{${parameter.name}}`, rendered);
	}
	return filled;
}

/** A copy-pasteable curl call for one operation. */
export function curlFor(
	operation: Operation,
	spec: OpenApiSpec,
	baseUrl: string,
	token: string
): string {
	const base = baseUrl.replace(/\/+$/, '');
	const url = `${base}${fillPath(operation, spec)}`;
	const secret = token.trim() || '$KERMIT_TOKEN';
	const lines = [`curl -s ${operation.method === 'GET' ? '' : `-X ${operation.method} `}"${url}"`];
	lines.push(`  -H "Authorization: Bearer ${secret}"`);

	if (operation.requestSchema) {
		const body = JSON.stringify(sampleValue(operation.requestSchema, spec), null, 2)
			.split('\n')
			.join('\n  ');
		lines.push(`  -H "Content-Type: application/json"`);
		lines.push(`  -d '${body}'`);
	}
	return lines.join(' \\\n');
}
